from pathlib import Path
import html,json
root=Path(__file__).resolve().parents[1]
art=root/'artifacts'
mechanics=json.loads((art/'expansion38_mechanics.json').read_text())
native=json.loads((art/'expansion38_native.json').read_text())
views=[
 ('realm_world_1280','Thanh Nang Bí Cảnh','Sáu ô đất, ba giống cây và hai chuồng. Nhân vật sử dụng bộ asset 0.37 hiện có.'),
 ('ruins_world_1280','Tàn Tích Cổ Trận','Vùng chiến đấu riêng với quần thể sói, cổ tinh và chân nguyên thạch.'),
 ('travel_locked_1280','Địa đồ & nhiệm vụ mở vùng','T mở Địa đồ. Cổng kiểm tra vị trí, giao chiến và điều kiện mở khoá.'),
 ('gu_rank2_1280','Bảng Cổ • bậc II','G mở Bảng Cổ. Bậc, tu luyện và hệ số sức mạnh phản ánh mô phỏng thật.'),
 ('gu_recipe_1280','Công thức luyện hợp','Hiển thị nguyên liệu có/cần và Cổ phôi sẽ bị tiêu hao.'),
 ('farm_book_1280','Quản lý điền viên','H mở Bí cảnh. Gieo, tưới, cho ăn và thu hoạch cập nhật bản đồ và túi.'),
 ('farm_960','Bí cảnh ở 960 × 640','Cuộn để xem các ô đất và chuồng; tiêu đề và tab luôn hiện.'),
 ('gu_960','Bảng Cổ ở 960 × 640','Công thức co theo chiều rộng và cuộn dọc, không tràn ngang.'),
 ('travel_960','Địa đồ ở 960 × 640','Giữ đủ nút đóng, chuyển tab, khu vực và điều kiện dịch chuyển.'),
]
figures=''.join(f'<figure data-id="{name}"><img loading="lazy" src="expansion38_{name}.png" alt="{html.escape(title)}"><figcaption><strong>{html.escape(title)}</strong><p>{html.escape(desc)}</p></figcaption></figure>' for name,title,desc in views)
fx=''.join(f'<figure><img loading="lazy" src="expansion38_fx_{kind}_rank2.png" alt="{title}"><figcaption><strong>{title} • bậc II</strong><p>Dấu ấn dưới chân theo bậc Cổ; giữ điểm xuất chiêu, đường bay và phản hồi va chạm hiện có.</p></figcaption></figure>' for kind,title in [('cast_moon','Nguyệt Quang'),('shield','Bạch Ngọc'),('dash','Bạch Hạc'),('cast_frost','Băng Tằm')])
page='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Cổ giới 0.38 — bản chạy native</title><style>
*{box-sizing:border-box}body{margin:0;background:#20261f;color:#eddfc0;font:17px/1.55 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:46px 30px}header{max-width:850px;margin-bottom:34px}.eyebrow{color:#b8c89c;letter-spacing:.15em;font-size:12px}h1{font:clamp(30px,4vw,54px)/1.1 Georgia,serif;margin:15px 0}p{margin:12px 0;color:#c1c4b2}nav{display:flex;gap:10px;flex-wrap:wrap;margin:24px 0}a,button{color:#eee0bb;background:#354635;border:1px solid #69785a;padding:9px 15px;text-decoration:none;border-radius:3px;cursor:pointer;font:inherit}a:hover,button:hover{background:#4a5c44}.keys{border-left:2px solid #b0bd8a;padding:5px 20px}kbd{background:#d6c5a0;color:#292d26;padding:2px 6px;border-radius:2px}figure{margin:0 0 32px;background:#2a3027;border:1px solid #4b5342}img{width:100%;display:block}figcaption{padding:18px 22px}figcaption p{font-size:15px;margin:5px 0}.stats{display:flex;gap:25px;flex-wrap:wrap;margin-top:25px;color:#dceac6}.gallery{display:none}.gallery.active{display:block}.gallery.fx.active{display:grid}.fx{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.fx figure{margin:0}footer{margin-top:40px;border-top:1px solid #566049;padding-top:25px;color:#aaa}.hint{font-size:14px}@media(max-width:700px){main{padding:24px 12px}.fx{grid-template-columns:1fr}}
</style><main><header><div class="eyebrow">GU MASTER 2D / BẢN PHÁT TRIỂN 0.38</div><h1>Đi qua cổ trận.<br>Gieo lại một thế giới.</h1><p>Vùng khám phá mới nối chiến đấu, luyện Cổ và điền viên. Đây là ảnh chụp từ Godot PC; trang này dùng để xem bản triển khai, không chạy mô phỏng game.</p><div class="keys"><kbd>T</kbd> Địa đồ · <kbd>G</kbd> Bảng Cổ · <kbd>H</kbd> Bí cảnh · <kbd>E</kbd> Tương tác<br><kbd>WASD</kbd> Di chuyển · <kbd>Shift</kbd> Chạy · <kbd>1–4</kbd> Dùng Cổ</div><div class="stats">STATS</div></header><nav><button data-tab="world">Vùng & hệ thống</button><button data-tab="fx">Hiệu ứng kỹ năng</button><a href="expansion38_native.json">Kết quả native</a><a href="expansion38_mechanics.json">Kết quả cơ chế</a></nav><section class="gallery active" id="world">FIGURES</section><section class="gallery fx" id="fx">FX</section><footer><strong>Lộ trình chơi thử</strong><p>Hạ 1 sói → về trại, T đến Tàn Tích → gom 2 cổ tinh và hạ tổng 3 sói → đến cổ trận, mở T phục hồi Thanh Nang → T vào bí cảnh → H gieo/tưới và nuôi thú → G luyện Cổ.</p><p class="hint">Tiến độ lưu cùng nhân vật. Cây và thú phát triển theo thời gian chơi; pause hoặc thoát thì dừng. Đây vẫn là prototype PC chơi đơn, cần thêm nội dung và thử cân bằng dài hạn.</p></footer></main><script>document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('.gallery').forEach(s=>s.classList.toggle('active',s.id===b.dataset.tab))});</script></html>'''
page=page.replace('STATS',f'<span>{mechanics["passed"]}/{mechanics["passed"]+mechanics["failed"]} cơ chế</span><span>{native["passed"]}/{native["passed"]+native["failed"]} native</span><span>613/613 hồi quy</span>').replace('FIGURES',figures).replace('FX',fx)
(art/'expansion38_review.html').write_text(page,encoding='utf-8')
print('Built expansion38_review.html')
